import Darwin
import Foundation
import os.log

/// Installs and updates the app-managed `llama` CLI by fetching prebuilt binaries
/// from the same Hugging Face bucket the official `install.sh` uses, laid out the same way:
/// the real binary at `~/.llama-app/llama` plus a `~/.local/bin/llama` symlink
/// so `llama` works from a terminal too.
///
/// macOS ships no zstd and the bucket serves the binary zstd-compressed, so we
/// fetch the bucket's small standalone `unzstd` helper (cached alongside the
/// binary) and pipe the download through it.
///
/// This only ever writes the managed path. A Homebrew (or other unmanaged)
/// install is never touched -- see `LlamaBinaries`.
enum LlamaInstaller {

  private static let logger = Logger(subsystem: Logging.subsystem, category: "LlamaInstaller")

  /// Root of the prebuilt-binary bucket. `…/resolve/latest` returns the current
  /// version tag (e.g. `b9553`); `…/resolve/<ver>/<arch>/<os>/…` are artifacts.
  private static let bucketBase =
    "https://huggingface.co/buckets/ggml-org/install.sh/resolve"

  /// We only ship prebuilt Apple Silicon (Metal) macOS binaries.
  private static let arch = "aarch64"
  private static let os = "macos"

  /// The real binary path (also what `LlamaBinaries` resolves as `.managed`).
  private static var llamaPath: String { LlamaBinaries.managedPath }

  /// Install dir the app manages. Holds the binary and the cached `unzstd` helper.
  private static var installDir: String {
    (LlamaBinaries.managedPath as NSString).deletingLastPathComponent
  }
  private static var unzstdPath: String { installDir + "/unzstd" }

  /// Where a background update is staged. The live path never changes under a
  /// running server; a staged binary is promoted (renamed over `llamaPath`) at
  /// the next app launch, before the server starts.
  static var stagedPath: String { LlamaBinaries.managedPath + ".staged" }

  /// The on-PATH symlink `install.sh` creates so `llama` works in a terminal.
  private static var symlinkDir: String {
    (NSHomeDirectory() as NSString).appendingPathComponent(".local/bin")
  }
  private static var symlinkPath: String { symlinkDir + "/llama" }

  enum InstallError: Error, LocalizedError {
    case unsupportedHardware(String)
    case downloadFailed(String)
    case decompressFailed(String)
    case installFailed(String)

    var errorDescription: String? {
      switch self {
      case .unsupportedHardware(let detail):
        return "No prebuilt llama binary for this Mac (\(detail))."
      case .downloadFailed(let detail):
        return "Download failed: \(detail)"
      case .decompressFailed(let detail):
        return "Couldn't unpack the llama binary: \(detail)"
      case .installFailed(let detail):
        return "Couldn't install the llama binary: \(detail)"
      }
    }
  }

  // MARK: - Public API

  /// Installs (or replaces) the app-managed `llama` binary at `version`.
  /// With `staged: true` the binary lands at `stagedPath` instead of the live
  /// path, to be promoted at the next launch -- used for background updates so
  /// the binary a running server spawns model instances from never changes
  /// underneath it.
  static func install(version: String, staged: Bool = false) async throws {
    logger.info("Installing llama \(version, privacy: .public)\(staged ? " (staged)" : "")")

    let config = try metalConfig()
    try await ensureUnzstd(version: version)

    let zstURL = try await download(
      "\(bucketBase)/\(version)/\(arch)/\(os)/metal/\(config)/llama-app.zst")
    defer { try? FileManager.default.removeItem(at: zstURL) }

    let dest = staged ? stagedPath : llamaPath
    try decompress(zst: zstURL, to: dest)
    if !staged { linkOnPath() }

    logger.info("Installed llama \(version, privacy: .public) at \(dest, privacy: .public)")
  }

  /// Promotes a staged binary into the live path if it matches `target`, else
  /// discards it (the pin moved on since it was staged). Call at launch, before
  /// the server starts. Runs a `version` subprocess, so call off the main
  /// thread.
  static func promoteStaged(target: LlamaVersion) {
    let fm = FileManager.default
    guard fm.isExecutableFile(atPath: stagedPath) else { return }

    guard LlamaBinaries.readVersion(at: stagedPath) == target else {
      logger.info("Discarding stale staged llama binary")
      try? fm.removeItem(atPath: stagedPath)
      return
    }

    guard rename(stagedPath, llamaPath) == 0 else {
      logger.error("Couldn't promote staged llama binary: \(String(cString: strerror(errno)))")
      try? fm.removeItem(atPath: stagedPath)
      return
    }
    linkOnPath()
    logger.info("Promoted staged llama binary \(target.tag, privacy: .public)")
  }

  // MARK: - Steps

  /// Maps this Mac's CPU to a Metal bucket config (`m1`…`m5`, `a18`), mirroring
  /// `install.sh`, which buckets every M-series variant (Pro/Max/Ultra) by
  /// generation number and also accepts the A18 (non-M MacBook).
  private static func metalConfig() throws -> String {
    var size = 0
    sysctlbyname("machdep.cpu.brand_string", nil, &size, nil, 0)
    guard size > 0 else { throw InstallError.unsupportedHardware("unknown CPU") }
    var buf = [CChar](repeating: 0, count: size)
    sysctlbyname("machdep.cpu.brand_string", &buf, &size, nil, 0)
    let brand = String(cString: buf)

    guard let range = brand.range(of: "Apple (M[1-5]|A18)", options: .regularExpression)
    else {
      throw InstallError.unsupportedHardware(brand)
    }
    return brand[range].dropFirst("Apple ".count).lowercased()
  }

  /// Ensures the `unzstd` helper is present, fetching it once and caching it
  /// next to the binary. Subsequent installs/updates reuse it.
  private static func ensureUnzstd(version: String) async throws {
    if FileManager.default.isExecutableFile(atPath: unzstdPath) { return }
    let tmp = try await download("\(bucketBase)/\(version)/\(arch)/\(os)/unzstd")
    defer { try? FileManager.default.removeItem(at: tmp) }
    try atomicInstall(from: tmp, to: unzstdPath)
  }

  /// Decompresses `zst` through the `unzstd` helper and atomically swaps the
  /// result into `dest`. The temp output lives in `installDir` so the final
  /// `rename(2)` is a same-volume atomic replace -- a crash never leaves a
  /// half-written binary in place.
  private static func decompress(zst: URL, to dest: String) throws {
    let fm = FileManager.default
    try fm.createDirectory(atPath: installDir, withIntermediateDirectories: true)

    let tmpOut = installDir + "/llama.tmp-\(UUID().uuidString)"
    guard fm.createFile(atPath: tmpOut, contents: nil) else {
      throw InstallError.decompressFailed("couldn't create \(tmpOut)")
    }

    do {
      guard let outHandle = FileHandle(forWritingAtPath: tmpOut) else {
        throw InstallError.decompressFailed("couldn't open \(tmpOut)")
      }
      let inHandle = try FileHandle(forReadingFrom: zst)
      let errPipe = Pipe()

      // unzstd with no args decompresses stdin -> stdout.
      let proc = Process()
      proc.executableURL = URL(fileURLWithPath: unzstdPath)
      proc.standardInput = inHandle
      proc.standardOutput = outHandle
      proc.standardError = errPipe

      try proc.run()
      proc.waitUntilExit()
      try? inHandle.close()
      try? outHandle.close()

      guard proc.terminationStatus == 0 else {
        let err = String(
          decoding: errPipe.fileHandleForReading.readDataToEndOfFile(), as: UTF8.self)
        throw InstallError.decompressFailed(
          "unzstd exited \(proc.terminationStatus): \(err.prefix(200))")
      }

      try fm.setAttributes([.posixPermissions: 0o755], ofItemAtPath: tmpOut)
      guard rename(tmpOut, dest) == 0 else {
        throw InstallError.installFailed("rename: \(String(cString: strerror(errno)))")
      }
    } catch {
      try? fm.removeItem(atPath: tmpOut)
      throw error
    }
  }

  /// Mirrors `install.sh`'s `ln -sf`: point `~/.local/bin/llama` at our
  /// binary so it's available in a terminal. Best-effort -- the app resolves the
  /// real path directly, so a failure here doesn't break the app. We won't
  /// clobber a real file a user may have placed there; only absent or symlink
  /// entries are (re)written.
  private static func linkOnPath() {
    let fm = FileManager.default
    do {
      try fm.createDirectory(atPath: symlinkDir, withIntermediateDirectories: true)

      if (try? fm.destinationOfSymbolicLink(atPath: symlinkPath)) != nil {
        try fm.removeItem(atPath: symlinkPath)  // replace our (or any) existing symlink
      } else if fm.fileExists(atPath: symlinkPath) {
        logger.info("Leaving existing non-symlink at \(symlinkPath, privacy: .public)")
        return
      }
      try fm.createSymbolicLink(atPath: symlinkPath, withDestinationPath: llamaPath)
    } catch {
      logger.error("Couldn't create PATH symlink: \(error.localizedDescription, privacy: .public)")
    }
  }

  // MARK: - Helpers

  /// Downloads a URL to a temp file, following HF's redirect to the CDN.
  private static func download(_ urlString: String) async throws -> URL {
    guard let url = URL(string: urlString) else {
      throw InstallError.downloadFailed("bad URL: \(urlString)")
    }
    let request = HFRequest.make(url, token: await HFAuth.token())
    let (tempURL, response) = try await URLSession.shared.download(for: request)
    guard let http = response as? HTTPURLResponse, (200..<300).contains(http.statusCode) else {
      let code = (response as? HTTPURLResponse)?.statusCode ?? -1
      throw InstallError.downloadFailed("\(urlString) (HTTP \(code))")
    }
    return tempURL
  }

  /// Copies `src` (possibly on another volume) onto the destination volume, then
  /// atomically renames it into place as an executable.
  private static func atomicInstall(from src: URL, to dest: String) throws {
    let fm = FileManager.default
    try fm.createDirectory(
      atPath: (dest as NSString).deletingLastPathComponent, withIntermediateDirectories: true)

    let tmp = dest + ".tmp-\(UUID().uuidString)"
    do {
      try fm.copyItem(at: src, to: URL(fileURLWithPath: tmp))
      try fm.setAttributes([.posixPermissions: 0o755], ofItemAtPath: tmp)
      guard rename(tmp, dest) == 0 else {
        throw InstallError.installFailed("rename \(dest): \(String(cString: strerror(errno)))")
      }
    } catch {
      try? fm.removeItem(atPath: tmp)
      throw error
    }
  }
}

import AppKit

/// Surfaces the app-owned CLI install in the menu: a "setting up…" banner while
/// installing, or an error with a retry link if it failed. Shown only when the
/// install manager is mid-install or has failed; a ready binary shows nothing.
final class CLISetupView: ItemView {
  override var highlightEnabled: Bool { false }

  private let state: LlamaInstallManager.State

  init(state: LlamaInstallManager.State) {
    self.state = state
    super.init(frame: .zero)
    setup()
  }

  required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }

  private func setup() {
    widthAnchor.constraint(equalToConstant: Layout.menuWidth).isActive = true

    let views: [NSView]
    switch state {
    case .installing:
      let title = Theme.primaryLabel("Setting up llama…")
      let description = wrappingLabel(
        "Downloading the engine. This only happens once.")
      views = [title, description]

    case .failed(let message):
      let title = Theme.primaryLabel("Couldn’t download engine")
      let description = wrappingLabel(
        "Llama needs to download llama.cpp once, but the download failed. " + message)
      views = [title, description, actionLink("Retry")]

    case .unmanagedTooOld(let version):
      let title = Theme.primaryLabel("Update llama.cpp")
      let description = wrappingLabel(
        "Your llama.cpp (\(version.tag)) is older than the recommended "
          + "\(LlamaBinaries.floorVersion.tag). Update it with “brew upgrade llama.cpp”.")
      views = [title, description, actionLink("Re-check")]

    case .idle:
      // Not rendered when idle; guard anyway so the view is never blank-but-present.
      views = []
    }

    let stack = NSStackView(views: views)
    stack.orientation = .vertical
    stack.alignment = .leading
    stack.spacing = Layout.textLineSpacing
    if views.count >= 2 { stack.setCustomSpacing(8, after: views[1]) }

    contentView.addSubview(stack)
    stack.pinToSuperview()
  }

  /// A tappable link row (e.g. "Retry") that re-runs the CLI readiness check.
  private func actionLink(_ title: String) -> NSTextField {
    let link = Theme.secondaryLabel()
    link.attributedStringValue = NSAttributedString(
      string: title,
      attributes: [.foregroundColor: NSColor.linkColor, .font: Theme.Fonts.secondary])
    link.isSelectable = false
    addGesture(to: link, action: #selector(recheck))
    return link
  }

  private func wrappingLabel(_ text: String) -> NSTextField {
    let label = Theme.tertiaryLabel(text)
    label.cell?.wraps = true
    label.cell?.isScrollable = false
    label.usesSingleLineMode = false
    label.maximumNumberOfLines = 0
    label.lineBreakMode = .byWordWrapping
    label.preferredMaxLayoutWidth = Layout.contentWidth
    return label
  }

  @objc private func recheck() {
    LlamaInstallManager.shared.startServerWhenReady()
  }
}

import AppKit

/// A labeled action row on a model page: leading SF symbol glyph + title,
/// styled like a regular menu item (hover highlight, full-row click target).
/// Used instead of bezel buttons, which read as dialog chrome inside a menu
/// and gray out whenever the app isn't frontmost (menu bar apps usually
/// aren't).
final class ActionItemView: ItemView {
  /// Settable so a row's action can reference the row itself (e.g. Copy model
  /// ID flashing its own confirmation) without a retain cycle at init.
  var onAction: () -> Void
  private let iconView = NSImageView()
  private let symbol: String
  private let label: NSTextField
  private let title: String

  /// When non-nil, the row confirms inline instead of firing on first click:
  /// the first click arms it (swapping the label to `confirmTitle`), and only a
  /// second click within `confirmWindow` runs `onAction`. Disarms on hover-out
  /// or timeout, restoring the original title. Nil = fire immediately.
  private let confirmTitle: String?
  private var isArmed = false
  private var disarmWorkItem: DispatchWorkItem?
  private static let confirmWindow: TimeInterval = 3.0

  /// - Parameters:
  ///   - title: Row label, e.g. "Chat".
  ///   - symbol: SF symbol name for the leading glyph.
  ///   - detail: Optional trailing metadata (e.g. Delete's disk footprint).
  ///   - confirmTitle: When set, requires an inline two-step confirm (see above).
  ///   - onAction: Invoked on click (or the confirming second click).
  init(
    title: String,
    symbol: String,
    detail: String? = nil,
    confirmTitle: String? = nil,
    onAction: @escaping () -> Void
  ) {
    self.onAction = onAction
    self.symbol = symbol
    self.title = title
    self.confirmTitle = confirmTitle
    self.label = Theme.primaryLabel(title)
    super.init(frame: .zero)

    // Every row shares one style, including Delete: the trash glyph and the
    // inline confirm carry the destructiveness, so a red tint would only pull
    // the eye toward the item you least want misclicked.
    Theme.configure(iconView, symbol: symbol, color: Theme.Colors.modelIconTint, pointSize: 12)

    // Fixed-width glyph slot so labels column-align across rows regardless of
    // each symbol's natural width.
    iconView.translatesAutoresizingMaskIntoConstraints = false
    iconView.widthAnchor.constraint(equalToConstant: 20).isActive = true

    let stack = NSStackView(views: [iconView, label])
    stack.orientation = .horizontal
    stack.alignment = .centerY
    stack.spacing = 4

    // Trailing metadata in the dimmed secondary style, pushed to the far
    // edge -- context for the action, not part of its label.
    if let detail {
      stack.addArrangedSubview(.flexibleSpacer())
      let detailLabel = Theme.secondaryLabel(detail)
      detailLabel.textColor = Theme.Colors.textSecondary
      stack.addArrangedSubview(detailLabel)
    }
    contentView.addSubview(stack)
    stack.pinToSuperview()

    NSLayoutConstraint.activate([
      widthAnchor.constraint(equalToConstant: Layout.menuWidth),
      heightAnchor.constraint(equalToConstant: 28),
    ])

    addGesture(action: #selector(didClick))
  }

  required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }

  /// Briefly swaps the glyph for a checkmark to confirm the action landed
  /// (used by Copy model ID). Restores the original symbol after a beat.
  func flashConfirmation() {
    Theme.configure(iconView, symbol: "checkmark", color: Theme.Colors.modelIconTint, pointSize: 12)
    DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) { [weak self] in
      guard let self else { return }
      Theme.configure(
        self.iconView, symbol: self.symbol, color: Theme.Colors.modelIconTint, pointSize: 12)
    }
  }

  @objc private func didClick() {
    // No inline confirmation configured -- fire straight away.
    guard let confirmTitle else {
      onAction()
      return
    }
    // First click arms; second (confirming) click within the window fires.
    if isArmed {
      disarm()
      onAction()
    } else {
      arm(with: confirmTitle)
    }
  }

  /// Swaps the label to the confirm prompt and schedules an auto-disarm so a
  /// stray first click doesn't leave the row stuck in its armed state.
  private func arm(with confirmTitle: String) {
    isArmed = true
    label.stringValue = confirmTitle
    let workItem = DispatchWorkItem { [weak self] in self?.disarm() }
    disarmWorkItem = workItem
    DispatchQueue.main.asyncAfter(deadline: .now() + Self.confirmWindow, execute: workItem)
  }

  /// Restores the original label and cancels any pending auto-disarm.
  private func disarm() {
    disarmWorkItem?.cancel()
    disarmWorkItem = nil
    guard isArmed else { return }
    isArmed = false
    label.stringValue = title
  }

  /// Disarm when the pointer leaves the row -- moving away is an implicit cancel.
  override func highlightDidChange(_ highlighted: Bool) {
    super.highlightDidChange(highlighted)
    if !highlighted { disarm() }
  }
}

import AppKit

/// Placeholder shown under the Installed header when no models are installed yet.
///
/// Replaces a flush-left line of tertiary text that read as a header subtitle.
/// Instead it occupies the same footprint as a model row — same width and 40pt
/// height — with centered text and a subtle dashed outline, so it reads as an
/// empty slot waiting to be filled. Matching the row height also means the menu
/// doesn't resize the moment the first download replaces this with a real row.
final class EmptyInstalledRow: ItemView {
  // Dashed rounded outline tracing the content area, to signal "an empty slot
  // goes here." Drawn on contentView (not backgroundView) so it stops at the
  // content edge — a permanent element shouldn't bleed into the menu's side
  // margins; only the transient hover highlight is allowed to.
  private let outline = CAShapeLayer()

  init() {
    super.init(frame: .zero)

    let label = Theme.tertiaryLabel("No models yet")
    label.alignment = .center
    contentView.addSubview(label)
    // Center in the row rather than pinning to the leading edge — centered text
    // reads as a placeholder, not a header label.
    label.translatesAutoresizingMaskIntoConstraints = false
    NSLayoutConstraint.activate([
      label.centerXAnchor.constraint(equalTo: contentView.centerXAnchor),
      label.centerYAnchor.constraint(equalTo: contentView.centerYAnchor),
    ])

    // Same footprint as a model row (ModelItemView / CatalogItemView).
    NSLayoutConstraint.activate([
      widthAnchor.constraint(equalToConstant: Layout.menuWidth),
      heightAnchor.constraint(equalToConstant: 40),
    ])

    outline.fillColor = nil
    outline.lineWidth = 1
    outline.lineDashPattern = [4, 3]
    contentView.wantsLayer = true
    contentView.layer?.addSublayer(outline)
    refreshOutlineColor()
  }

  required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }

  // Static placeholder — no hover affordance.
  override var highlightEnabled: Bool { false }

  override func layout() {
    super.layout()
    // Trace the content area, inset half a line so the stroke isn't clipped by
    // the layer bounds.
    let rect = contentView.bounds.insetBy(dx: 0.5, dy: 0.5)
    outline.frame = contentView.bounds
    outline.path = CGPath(
      roundedRect: rect, cornerWidth: Layout.cornerRadius, cornerHeight: Layout.cornerRadius,
      transform: nil)
  }

  override func viewDidChangeEffectiveAppearance() {
    super.viewDidChangeEffectiveAppearance()
    refreshOutlineColor()
  }

  private func refreshOutlineColor() {
    // CAShapeLayer takes a CGColor, so resolve the dynamic border color for the
    // current appearance.
    effectiveAppearance.performAsCurrentDrawingAppearance {
      outline.strokeColor = Theme.Colors.border.cgColor
    }
  }
}

