import Foundation

/// A speculative-decoding draft head the app drives: a small extra network
/// that drafts the next few tokens cheaply, which llama-server then verifies
/// against the main weights in one pass. Both kinds borrow the target model's
/// embeddings and output projection, so neither runs as a model on its own.
///
/// Only models trained with a head have one -- the app can't add it. A repo
/// ships it as a sidecar GGUF named by its kind's prefix (`mtp-….gguf`,
/// `dflash-….gguf`); an MTP head can also be embedded in the main weights.
enum DraftHead: String, Codable {
  /// Multi-token prediction: the head predicts a few tokens ahead.
  case mtp
  /// Block-diffusion drafting: the head fills a whole block of tokens at once.
  case dflash

  /// Kinds in order of preference, for repos that ship more than one head.
  /// DFlash wins: on Qwen3.8-27B (Q8_0, M5 Max, engine b11429) it generated
  /// 35-50% faster than MTP, and the llama.cpp maintainers recommend it over
  /// MTP whenever a model has both. Models that ship only an MTP head keep it.
  static let preferenceOrder: [DraftHead] = [.dflash, .mtp]

  /// The sidecar's filename prefix -- the convention llama.cpp keys on when it
  /// resolves heads shipped beside a model (`find_best_sibling` callers in
  /// `common/download.cpp`).
  var sidecarPrefix: String {
    switch self {
    case .mtp: "mtp-"
    case .dflash: "dflash-"
    }
  }

  /// The kind of the sidecar at `path`, judged by its basename; nil when it
  /// isn't a draft-head sidecar we drive. Accepts full repo-relative paths.
  init?(sidecarPath path: String) {
    let name = (path as NSString).lastPathComponent.lowercased()
    guard name.hasSuffix(".gguf"),
      let kind = Self.preferenceOrder.first(where: { name.hasPrefix($0.sidecarPrefix) })
    else { return nil }
    self = kind
  }

  /// The `spec-type` value that tells llama-server to draft with this head.
  var specType: String {
    switch self {
    case .mtp: "draft-mtp"
    case .dflash: "draft-dflash"
    }
  }

  /// Cap on tokens drafted per step (`spec-draft-n-max`), the values the
  /// llama.cpp maintainers recommend. MTP only predicts a few tokens ahead
  /// reliably, so drafting deeper wastes compute on tokens the target rejects;
  /// DFlash drafts a block at a time and stays accurate further out.
  var draftNMax: Int {
    switch self {
    case .mtp: 3
    case .dflash: 7
    }
  }

  /// Name shown in the model row's chip.
  var label: String {
    switch self {
    case .mtp: "MTP"
    case .dflash: "DFlash"
    }
  }
}

import Foundation

/// Resolved file paths for a downloaded model.
/// Separates "what is this model" (`Model`) from "where is it on disk".
struct ResolvedPaths {
  /// Absolute path to the main model file
  let modelFile: String
  /// Absolute paths to additional shard files (multi-part models)
  let additionalParts: [String]
  /// Absolute path to the mmproj file (vision models), nil if not applicable
  let mmprojFile: String?
  /// Whether the main GGUF carries an *embedded* multi-token-prediction (MTP)
  /// head. When true we hand llama-server `spec-type = draft-mtp` so it uses
  /// the head for speculative decoding (a free ~2x on the MoE families that
  /// ship it). Detected from the filename -- these builds tag themselves with
  /// an `mtp` token (e.g. `…-Q4_K_M-mtp.gguf`, `…-MTP-Q8_0.gguf`).
  let usesMTP: Bool
  /// Absolute path to a *sidecar* draft head (`dflash-….gguf` or `mtp-….gguf`)
  /// shipped beside the main weights, nil when absent; its kind is
  /// `draftSidecarKind`. When set we pass it to llama-server as
  /// `spec-draft-model` alongside that kind's `spec-type`. Takes precedence over
  /// `usesMTP` -- a sidecar is what the repo's authors chose to ship for
  /// drafting, and a DFlash one beats an embedded MTP head outright.
  let draftSidecarFile: String?
  /// Whether llama-server has to take each input to this model in a single
  /// batch, which makes the batch size -- not the context -- the longest input
  /// it accepts. True for embedding models (they attend in both directions)
  /// and for decision models llama.cpp scores from its embeddings output in
  /// one pass (`laya`, `clef`, `lfm2-d1-omni` -- see
  /// `common_init_result` in llama.cpp's `common.cpp`). `models.ini` sizes
  /// their batches to the context.
  let batchesWholeInput: Bool
  /// HF cache repo directory name (e.g. "models--bartowski--Llama-3.2-1B-Instruct-GGUF").
  /// Used by deletion to clean up the per-repo directory tree.
  let hfRepoDirName: String

  init(
    modelFile: String,
    additionalParts: [String],
    mmprojFile: String?,
    usesMTP: Bool = false,
    draftSidecarFile: String? = nil,
    batchesWholeInput: Bool = false,
    hfRepoDirName: String
  ) {
    self.modelFile = modelFile
    self.additionalParts = additionalParts
    self.mmprojFile = mmprojFile
    self.usesMTP = usesMTP
    self.draftSidecarFile = draftSidecarFile
    self.batchesWholeInput = batchesWholeInput
    self.hfRepoDirName = hfRepoDirName
  }

  /// The kind of `draftSidecarFile`, read from its filename prefix.
  var draftSidecarKind: DraftHead? {
    draftSidecarFile.flatMap { DraftHead(sidecarPath: $0) }
  }

  /// All file paths this model occupies on disk
  var allPaths: [String] {
    var paths = [modelFile]
    paths.append(contentsOf: additionalParts)
    if let mmproj = mmprojFile {
      paths.append(mmproj)
    }
    if let draft = draftSidecarFile {
      paths.append(draft)
    }
    return paths
  }
}

import Foundation

/// Represents a context length tier for running models.
/// Fixed tiers: 4K (chat/scripts), 32K (agents), and max supported tier.
enum ContextTier: Int, CaseIterable, Identifiable, Comparable {
  case k4 = 4096
  case k8 = 8192
  case k16 = 16384
  case k32 = 32768
  case k64 = 65536
  case k128 = 131072
  case k256 = 262144

  var id: Int { rawValue }

  /// Number-only label without the "ctx" suffix (e.g. "4k").
  /// Used for the context-size segments in the expanded model detail picker.
  var shortLabel: String { "\(rawValue / 1024)k" }

  var label: String { "\(shortLabel) ctx" }

  var suffix: String {
    ":\(label)"
  }

  static func < (lhs: ContextTier, rhs: ContextTier) -> Bool {
    lhs.rawValue < rhs.rawValue
  }

  /// The standard tiers shown in the UI (when compatible).
  static let standardTiers: [ContextTier] = [.k4, .k8, .k16, .k32, .k64, .k128]
}
